head.script:
scwin.onpageload = function () {
    cm_pop.setJSON([
        { id : "a", label : "Alpha", depth : 1 },
        { id : "b", label : "Beta", depth : 1 },
        { id : "c", label : "Gamma", depth : 1 },
        { id : "d", label : "Delta", depth : 1 }
    ]);
};

// 메뉴가 열리면 본 화면에 결과 출력
scwin.cm_pop_onopen = function (info) {
    $p.parent().scwin.checkVisible(cm_pop, "팝업 안 메뉴 열기");
};
